#!/usr/bin/env bash
set -euo pipefail
cd "$CC_EVAL_WORKSPACE"
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
cp .fvmrc "$tmp/.fvmrc"
cp lib/run_stage.dart "$tmp/run_stage.dart"
cp lib/agent_process_event.dart "$tmp/agent_process_event.dart"
cat > "$tmp/probe.dart" <<'DART'
import 'run_stage.dart';
import 'agent_process_event.dart';

void expect(bool condition, String message) {
  if (!condition) throw StateError(message);
}

void main() {
  const sent = RunStageTiming(stage: RunStage.requestSent, offsetMs: 100,
      source: RunTimingSource.transport, provider: 'gateway', requestId: 'attempt-1');
  const byteOther = RunStageTiming(stage: RunStage.firstResponseByte, offsetMs: 190,
      source: RunTimingSource.transport, provider: 'gateway', requestId: 'attempt-2');
  const deltaOther = RunStageTiming(stage: RunStage.firstModelDelta, offsetMs: 210,
      source: RunTimingSource.provider, provider: 'gateway', requestId: 'attempt-2');
  expect(sent.toJson()['requestId'] == 'attempt-1', 'domain JSON writes physical identity');
  final restored = RunStageTiming.fromJson(sent.toJson());
  expect(restored?.requestId == 'attempt-1', 'domain JSON reads physical identity');
  expect(restored == sent, 'domain JSON preserves timing equality');
  final unrelated = RunLatencyProfile.fromJson([sent.toJson(), byteOther.toJson(), deltaOther.toJson()]);
  expect(unrelated.transportTtfbMs == null, 'retry cannot borrow prior request first byte');
  expect(unrelated.providerTtftMs == null, 'retry cannot borrow prior request first delta');
  const byteSame = RunStageTiming(stage: RunStage.firstResponseByte, offsetMs: 135,
      source: RunTimingSource.transport, provider: 'gateway', requestId: 'attempt-1');
  const deltaSame = RunStageTiming(stage: RunStage.firstModelDelta, offsetMs: 155,
      source: RunTimingSource.provider, provider: 'gateway', requestId: 'attempt-1');
  final matched = RunLatencyProfile.empty.mergeAll([sent, byteSame, deltaSame]);
  expect(matched.transportTtfbMs == 35 && matched.providerTtftMs == 55,
      'same request retains genuine transport and provider intervals');
  expect(RunLatencyProfile.fromJson(matched.toJson()).providerTtftMs == 55,
      'profile round trip preserves same-request interval');
  final event = StageTimingEvent(stage: RunStage.firstModelDelta, offsetMs: 155,
      source: RunTimingSource.provider, provider: 'gateway', requestId: 'attempt-1');
  expect(event.metadata?['requestId'] == 'attempt-1', 'event serializes identity');
  final fromEvent = event.toTiming();
  expect(fromEvent.requestId == 'attempt-1', 'event forwards identity to domain');
  expect(RunLatencyProfile.empty.mergeAll([sent, fromEvent]).providerTtftMs == 55,
      'event consumer can calculate same-physical-request latency');
  final untagged = StageTimingEvent(stage: RunStage.firstResponseByte, offsetMs: 160,
      source: RunTimingSource.transport);
  expect(!untagged.metadata!.containsKey('requestId'), 'unknown identity stays absent');
  expect(RunLatencyProfile.empty.mergeAll([sent, untagged.toTiming()]).transportTtfbMs == null,
      'unknown identity must not match a tagged request');
}
DART
(cd "$tmp" && fvm dart probe.dart)

