        return (input['allowed_email'] as String).toLowerCase() ==
            (input['email'] as String).toLowerCase();
      case 'overlap-count':
        return (input['a_start'] as num) < (input['b_end'] as num) &&
            (input['b_start'] as num) < (input['a_end'] as num);
