import 'package:cc_domain/features/fleet/domain/entities/job.dart';
import 'package:cc_domain/features/fleet/domain/entities/worker.dart';
import 'package:cc_domain/features/fleet/domain/value_objects/placement_decision.dart';

/// The current runtime view of the fleet a placement is computed against.
///
/// Pure data — the scheduler takes a snapshot and never touches the DB, so the
/// same snapshot + same job always yields the same [PlacementDecision]
/// (determinism invariant, PRD 20 design tenet 4).
class FleetSnapshot {
  /// Creates a [FleetSnapshot].
  const FleetSnapshot({
    required this.workers,
    this.busyWorkerIds = const {},
    this.cacheWarmWorkerIds = const {},
  });

  /// Every known worker (any status).
  final List<Worker> workers;

  /// Worker ids currently at capacity (cannot take another job now).
  final Set<String> busyWorkerIds;

  /// Worker ids whose repo cache is already warm for the job's repo.
  final Set<String> cacheWarmWorkerIds;
}

/// The deterministic, capability-matched job scheduler (PRD 20 §2).
///
/// Placement is by declared capability + explicit policy, never load-balancer
/// vibes: pin → prefer → spill. Given the same [FleetSnapshot] and [Job], the
/// decision is identical every time (ties break on worker id). The scheduler is
/// a pure function; leasing, streaming and side effects live in the server.
class JobScheduler {
  /// Creates a [JobScheduler].
  const JobScheduler();

  /// Decides where (if anywhere) [job] should run given [snapshot].
  PlacementDecision place(Job job, FleetSnapshot snapshot) {
    final schedulable = snapshot.workers.where((w) => w.isSchedulable).toList()
      ..sort((a, b) => a.id.compareTo(b.id));

    // 1. Explicit pin wins, unconditionally and deterministically.
    if (job.isPinned) {
      return _placePinned(job, snapshot, schedulable);
    }

    // 2. Which schedulable workers can run this job at all?
    final capable = schedulable
        .where((w) => w.capabilityKeys.containsAll(job.requiredCaps))
        .toList();
    if (capable.isEmpty) {
      // Distinguish "no worker anywhere can" from "some can but are offline".
      final anyCapableAtAll = snapshot.workers.any(
        (w) => w.capabilityKeys.containsAll(job.requiredCaps),
      );
      if (!anyCapableAtAll) {
        final missing = _missingCaps(job, snapshot.workers);
        return PlacementDecision.queued(
          missing.isEmpty
              ? 'No worker in the fleet can run this job.'
              : 'No worker advertises required capability '
                    '${missing.join(", ")}.',
          code: PlacementCode.noCapableWorker,
        );
      }
      return const PlacementDecision.queued(
        'Capable workers exist but none are online.',
      );
    }

    // 3. Among capable workers, only the free ones can take it now.
    final free = capable
        .where((w) => !snapshot.busyWorkerIds.contains(w.id))
        .toList();
    if (free.isEmpty) {
      return PlacementDecision.queued(
        '${capable.length} capable worker(s), all busy — queued for the next '
        'free one.',
      );
    }

    // 4. Rank free workers: prefer preferred-cap matches, then cache-warm,
    //    then stable worker id. Highest score wins; ties break on id.
    Worker? best;
    var bestScore = -1;
    for (final w in free) {
      final satisfiesPreferred =
          job.preferredCaps.isNotEmpty &&
          w.capabilityKeys.containsAll(job.preferredCaps);
      final cacheWarm = snapshot.cacheWarmWorkerIds.contains(w.id);
      final score = (satisfiesPreferred ? 100 : 0) + (cacheWarm ? 10 : 0);
      if (score > bestScore) {
        bestScore = score;
        best = w;
      }
    }
    final chosen = best!;
    final satisfiesPreferred =
        job.preferredCaps.isNotEmpty &&
        chosen.capabilityKeys.containsAll(job.preferredCaps);
    final cacheWarm = snapshot.cacheWarmWorkerIds.contains(chosen.id);
    final cacheNote = cacheWarm ? '' : ' (warming repo cache)';

    if (satisfiesPreferred) {
      return PlacementDecision(
        code: PlacementCode.preferred,
        workerId: chosen.id,
        reason:
            'Ran on ${chosen.name} — matched preferred '
            '${job.preferredCaps.join(", ")}$cacheNote.',
      );
    }
    return PlacementDecision(
      code: PlacementCode.spill,
      workerId: chosen.id,
      reason: 'Ran on ${chosen.name} — first free capable worker$cacheNote.',
    );
  }

  PlacementDecision _placePinned(
    Job job,
    FleetSnapshot snapshot,
    List<Worker> schedulable,
  ) {
    final pinId = job.pinnedWorkerId!;
    Worker? pinned;
    for (final w in schedulable) {
      if (w.id == pinId) {
        pinned = w;
        break;
      }
    }
    if (pinned == null) {
      return PlacementDecision.queued(
        'Pinned worker $pinId is not online — queued until it returns.',
        code: PlacementCode.pinnedWorkerUnavailable,
      );
    }
    if (!pinned.capabilityKeys.containsAll(job.requiredCaps)) {
      final missing =
          job.requiredCaps.difference(pinned.capabilityKeys).toList()..sort();
      return PlacementDecision.queued(
        'Pinned worker ${pinned.name} lacks required capability '
        '${missing.join(", ")}.',
        code: PlacementCode.pinnedWorkerUnavailable,
      );
    }
    if (snapshot.busyWorkerIds.contains(pinned.id)) {
      return PlacementDecision.queued(
        'Pinned worker ${pinned.name} is busy — queued for it specifically.',
      );
    }
    return PlacementDecision(
      code: PlacementCode.pinned,
      workerId: pinned.id,
      reason: 'Ran on ${pinned.name} — explicitly pinned.',
    );
  }

  /// The required capability keys that no worker in [workers] advertises.
  Set<String> _missingCaps(Job job, List<Worker> workers) {
    final advertised = <String>{};
    for (final w in workers) {
      advertised.addAll(w.capabilityKeys);
    }
    return job.requiredCaps.difference(advertised);
  }
}

import 'package:cc_domain/features/dispatch/domain/entities/agent_process_event.dart';
import 'package:cc_domain/features/dispatch/domain/entities/agent_process_event_codec.dart';

/// The fleet wire-protocol version (PRD 20 Clarifications).
///
/// Worker and server exchange this at pairing and on every reconnect; a
/// mismatch marks the worker `incompatible` and withholds leases — never a
/// wire-format guess. Workers version with the server release (no compat
/// window, per the pre-1.0 no-compat rule).
const int kFleetProtocolVersion = 1;

/// A worker's self-description sent at registration and heartbeat (PRD 20 §1).
class WorkerRegistration {
  /// Creates a [WorkerRegistration].
  const WorkerRegistration({
    required this.name,
    required this.capsJson,
    required this.protocolVersion,
    this.platform = 'unknown',
  });

  /// Parses from a wire map.
  factory WorkerRegistration.fromJson(Map<String, dynamic> json) =>
      WorkerRegistration(
        name: json['name'] as String? ?? 'worker',
        capsJson: json['capsJson'] as String? ?? '{}',
        protocolVersion: (json['protocolVersion'] as num?)?.toInt() ?? 0,
        platform: json['platform'] as String? ?? 'unknown',
      );

  /// Operator-facing worker name.
  final String name;

  /// JSON-encoded `WorkerCapabilities`.
  final String capsJson;

  /// The worker's wire protocol version.
  final int protocolVersion;

  /// Coarse platform string.
  final String platform;

  /// Serializes to a wire map.
  Map<String, dynamic> toJson() => {
    'name': name,
    'capsJson': capsJson,
    'protocolVersion': protocolVersion,
    'platform': platform,
  };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is WorkerRegistration &&
          name == other.name &&
          capsJson == other.capsJson &&
          protocolVersion == other.protocolVersion &&
          platform == other.platform;

  @override
  int get hashCode => Object.hash(name, capsJson, protocolVersion, platform);
}

/// A lease handed to a worker: everything it needs to run one job (PRD 20 §2).
///
/// Secrets are the job-scoped, short-lived credentials in [env] (never the
/// owner's PAT) — held in memory, expired at job end (PRD 20 §5).
class LeaseOffer {
  /// Creates a [LeaseOffer].
  const LeaseOffer({
    required this.jobId,
    required this.workspaceId,
    required this.kind,
    required this.specJson,
    required this.leaseExpiresAtIso,
    this.env = const {},
    this.repoRemote,
    this.headSha,
    this.branch,
  });

  /// Parses from a wire map.
  factory LeaseOffer.fromJson(Map<String, dynamic> json) => LeaseOffer(
    jobId: json['jobId'] as String? ?? '',
    workspaceId: json['workspaceId'] as String? ?? '',
    kind: json['kind'] as String? ?? 'agentRun',
    specJson: json['specJson'] as String? ?? '{}',
    leaseExpiresAtIso: json['leaseExpiresAt'] as String? ?? '',
    env: ((json['env'] as Map?) ?? const {}).map(
      (k, v) => MapEntry(k.toString(), v.toString()),
    ),
    repoRemote: json['repoRemote'] as String?,
    headSha: json['headSha'] as String?,
    branch: json['branch'] as String?,
  );

  /// The job id.
  final String jobId;

  /// The owning workspace.
  final String workspaceId;

  /// The job kind wire string.
  final String kind;

  /// The kind-specific spec payload JSON.
  final String specJson;

  /// Lease expiry (server clock, ISO-8601). The worker keeps executing until
  /// this instant if it loses contact (short TTL; cheap renewal).
  final String leaseExpiresAtIso;

  /// Job-scoped credential env to inject (held in memory only).
  final Map<String, String> env;

  /// Canonical remote to materialize the worktree from.
  final String? repoRemote;

  /// Pinned SHA to materialize at.
  final String? headSha;

  /// Branch to check the worktree out on.
  final String? branch;

  /// Serializes to a wire map.
  Map<String, dynamic> toJson() => {
    'jobId': jobId,
    'workspaceId': workspaceId,
    'kind': kind,
    'specJson': specJson,
    'leaseExpiresAt': leaseExpiresAtIso,
    if (env.isNotEmpty) 'env': env,
    if (repoRemote != null) 'repoRemote': repoRemote,
    if (headSha != null) 'headSha': headSha,
    if (branch != null) 'branch': branch,
  };
}

/// A sequenced event a worker streams back for a running job (PRD 20 §3, §4).
///
/// The [seq] is monotonic per job so the server acks a high-water mark and the
/// worker replays from `lastAckedSeq` on reconnect (bounded ring buffer).
class WorkerEventFrame {
  /// Creates a [WorkerEventFrame].
  const WorkerEventFrame({
    required this.jobId,
    required this.seq,
    required this.event,
  });

  /// Parses from a wire map (reconstructs the typed event).
  factory WorkerEventFrame.fromJson(Map<String, dynamic> json) =>
      WorkerEventFrame(
        jobId: json['jobId'] as String? ?? '',
        seq: (json['seq'] as num?)?.toInt() ?? 0,
        event: AgentProcessEventCodec.fromWire(
          (json['event'] as Map).cast<String, dynamic>(),
        ),
      );

  /// The job the event belongs to.
  final String jobId;

  /// Monotonic per-job sequence number.
  final int seq;

  /// The typed process event.
  final AgentProcessEvent event;

  /// Serializes to a wire map.
  Map<String, dynamic> toJson() => {
    'jobId': jobId,
    'seq': seq,
    'event': AgentProcessEventCodec.toWire(event),
  };
}

/// A worker's terminal report for a job (PRD 20 §8).
class JobCompletionReport {
  /// Creates a [JobCompletionReport].
  const JobCompletionReport({
    required this.jobId,
    required this.success,
    this.resultJson,
    this.error,
    this.costCents = 0,
    this.eventsLost = 0,
    this.lastSeq = 0,
  });

  /// Parses from a wire map.
  factory JobCompletionReport.fromJson(Map<String, dynamic> json) =>
      JobCompletionReport(
        jobId: json['jobId'] as String? ?? '',
        success: json['success'] as bool? ?? false,
        resultJson: json['resultJson'] as String?,
        error: json['error'] as String?,
        costCents: (json['costCents'] as num?)?.toInt() ?? 0,
        eventsLost: (json['eventsLost'] as num?)?.toInt() ?? 0,
        lastSeq: (json['lastSeq'] as num?)?.toInt() ?? 0,
      );

  /// The job id.
  final String jobId;

  /// Whether the job succeeded.
  final bool success;

  /// Result payload JSON on success.
  final String? resultJson;

  /// Failure reason on failure.
  final String? error;

  /// Metered cost in cents.
  final int costCents;

  /// Events dropped during a disconnect (surfaced, never silent).
  final int eventsLost;

  /// The last event sequence emitted (final ack point).
  final int lastSeq;

  /// Serializes to a wire map.
  Map<String, dynamic> toJson() => {
    'jobId': jobId,
    'success': success,
    if (resultJson != null) 'resultJson': resultJson,
    if (error != null) 'error': error,
    'costCents': costCents,
    'eventsLost': eventsLost,
    'lastSeq': lastSeq,
  };
}

