#!/usr/bin/env bash
set -euo pipefail
cd "$CC_EVAL_WORKSPACE"
python3 -I - <<'PY'
import json
from pathlib import Path
r=json.loads(Path('workflow.json').read_text())
if not isinstance(r,dict) or set(r)!= {'steps','outcomes'} or not isinstance(r['steps'],list): raise SystemExit('workflow schema')
status={'first':None,'second':None}; protocol=None; wired=False; saw_incompatible_queued=False; saw_missing_executor_failure=False; saw_success=False
for action in r['steps']:
    if not isinstance(action,dict) or action.get('op') not in ('register','submit','tick','wire_executor','finish'): raise SystemExit('unknown action')
    op=action['op']
    if op=='register':
        if set(action) != {'op','protocolVersion'} or type(action['protocolVersion']) is not int: raise SystemExit('registration shape')
        protocol=action['protocolVersion']
        if protocol not in (1,2): raise SystemExit('unsupported test protocol')
    elif op=='submit':
        if set(action)!= {'op','job'} or action['job'] not in status or status[action['job']] is not None: raise SystemExit('invalid submit')
        if action['job']=='second' and not saw_missing_executor_failure: raise SystemExit('second job not dependent on first failure')
        status[action['job']]='queued'
    elif op=='tick':
        if set(action)!= {'op'} or protocol is None: raise SystemExit('tick before registration')
        for key,value in status.items():
            if value != 'queued': continue
            if protocol!=1:
                if key=='first': saw_incompatible_queued=True
                continue
            if not saw_incompatible_queued: raise SystemExit('protocol mismatch boundary skipped')
            if not wired:
                if key!='first': raise SystemExit('unwired second job')
                status[key]='failed'; saw_missing_executor_failure=True
            else:
                status[key]='running'
    elif op=='wire_executor':
        if set(action)!= {'op'} or not saw_missing_executor_failure: raise SystemExit('executor wired before missing-executor failure')
        wired=True
    else:
        if set(action)!= {'op','job'} or action['job']!='second' or status['second']!='running': raise SystemExit('finish before lease and start')
        status['second']='completed'; saw_success=True
if not (saw_incompatible_queued and saw_missing_executor_failure and saw_success): raise SystemExit('required dependency/error boundary missing')
if status != {'first':'failed','second':'completed'} or r['outcomes'] != status: raise SystemExit('terminal outcomes not generated by workflow')
PY

