#!/usr/bin/env bash
set -euo pipefail
cd "$CC_EVAL_WORKSPACE"
python3 -I - <<'PY'
import json
from pathlib import Path
r=json.loads(Path('tool_surface.json').read_text())
required={'whenWebFetchDisabled','whenWebFetchEnabled','supportsSubagents','nativeResumeSupported','mcpDiscoveryCacheSupported','overlapReadOnlyRequiresSafeTool'}
if not isinstance(r,dict) or set(r)!=required: raise SystemExit('incorrect routing record shape')
base=['read','write','edit','search','find','bash','read_output']
if r['whenWebFetchDisabled']!=base or r['whenWebFetchEnabled']!=base+['web_fetch']: raise SystemExit('conditional tool surfaces wrong')
for k,v in {'supportsSubagents':False,'nativeResumeSupported':False,'mcpDiscoveryCacheSupported':False,'overlapReadOnlyRequiresSafeTool':True}.items():
    if type(r[k]) is not bool or r[k]!=v: raise SystemExit('unsupported policy classification: '+k)
